def transform(grid):
    g = np.array(grid)
    bg = background(g)
    H, W = g.shape
    from collections import defaultdict
    d = defaultdict(list)
    for y, x in zip(*np.where(g != bg)):
        d[int(x + y)].append(int(y - x))
    segs = []
    for u, vs in d.items():
        vs = sorted(vs)
        cur = [vs[0]]
        for v in vs[1:]:
            if v == cur[-1] + 2:
                cur.append(v)
            else:
                segs.append((u, cur[0], cur[-1]))
                cur = [v]
        segs.append((u, cur[0], cur[-1]))
    segs.sort()
    out = g.copy()
    for i, a in enumerate(segs):
        for b in segs[i + 1:]:
            if b[0] == a[0]:
                continue
            lo, hi = max(a[1], b[1]), min(a[2], b[2])
            if lo > hi:
                continue
            changed = False
            for y in range(H):
                for x in range(W):
                    if a[0] < x + y < b[0] and lo <= y - x <= hi and out[y, x] == bg:
                        out[y, x] = 2
                        changed = True
            if changed:
                emit(out, f"Fill with 2 the band between diagonal segments on x+y={a[0]} and x+y={b[0]}, over their shared span y-x in [{lo},{hi}].")
    emit(out, "Final: every overlapping pair of parallel diagonal segments has the space between them filled with 2.")
    return out
